    <script>
    function toggleOtherPurpose(){var d=document.getElementById("purpose_dropdown"),o=document.getElementById("other_purpose");if(d.value==="Other"){o.classList.remove("hidden");o.required=true;o.focus()}else{o.classList.add("hidden");o.required=false;o.value=""}}
    function setMinCheckout(){document.getElementById("check_out").min=document.getElementById("check_in").value}
    document.getElementById("feedbackForm").addEventListener("submit",function(e){if(!this.checkValidity())return;var b=document.getElementById("submitBtn"),l=document.getElementById("btnLoader"),t=document.getElementById("btnText"),a=document.getElementById("btnArrow");b.disabled=true;b.style.opacity="0.7";b.style.cursor="not-allowed";l.classList.remove("hidden");a.classList.add("hidden");t.innerText="Submitting..."});
    var observer=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(entry.isIntersecting){entry.target.classList.add("visible");observer.unobserve(entry.target)}})},{threshold:0.06,rootMargin:"0px 0px -60px 0px"});
    document.querySelectorAll(".reveal-section").forEach(function(s){observer.observe(s)});
    </script>
</body>
</html>